import{_ as p,a0 as l,w as o,s as i,ao as b,I as r,x as e,a1 as n,A as u}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const g=JSON.parse('{"title":"为什么说 Kubernetes 是一辆翻斗车 | LCTT x X-CMD","titleTemplate":false,"description":"为什么说 Kubernetes 是一辆翻斗车 | LCTT (201906) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"为什么说 Kubernetes 是一辆翻斗车 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"为什么说 Kubernetes 是一辆翻斗车 | LCTT (201906) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201906/20190604 Kubernetes is a dump truck- Here-s why","title":"为什么说 Kubernetes 是一辆翻斗车","tag":"201906","desc":""},"relativePath":"201906/20190604 Kubernetes is a dump truck- Here-s why.md","filePath":"[post].md"}'),d={name:"201906/20190604 Kubernetes is a dump truck- Here-s why.md"};function m(a,t,f,T,k,K){const s=l("Link");return o(),i("div",null,[t[18]||(t[18]=b('<h1 id="为什么说-kubernetes-是一辆翻斗车" tabindex="-1">为什么说 Kubernetes 是一辆翻斗车 <a class="header-anchor" href="#为什么说-kubernetes-是一辆翻斗车" aria-label="Permalink to “为什么说 Kubernetes 是一辆翻斗车”">​</a></h1><blockquote><p>翻斗车是解决各种基本业务问题的优雅解决方案。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/201906/24/012846v737bts00uwk3qd7.jpg" alt=""></p><p>这篇文章写于 Kubernetes 的生日（6 月 7 日星期五）前夕。</p><p>翻斗车很优雅。说真的，不信你听我说。它们以优雅的方式解决了各种各样的技术问题。它们可以搬动泥土、砾石、岩石、煤炭、建筑材料或道路上的障碍。它们甚至可以拉动拖车及它们上面的其他重型设备。你可以给一辆翻斗车装上五吨泥土，然后自驾游遍全国。对于像我这样的电脑极客来说，那就是优雅。</p><p>但是，它们并不容易使用。驾驶翻斗车需要特殊的驾驶执照。它们也不容易装配和维护。购买翻斗车和各种维护时要做很多选择。但是，它们可以优雅的搬动那些垃圾。</p><p>你知道搬动垃圾有什么不优雅的地方吗？假如你有一款新型的紧凑型轿车，它们到处可以买到，易于驾驶、更易于维护。但是，用它们来装泥土就很糟糕。这需要跑 200 趟才能运走 5 吨垃圾，而且，之后没人再会想要这辆车了。</p><p>好吧，你可以买一辆出售的翻斗车，而不是想自己造一辆。但是我不同，我是个极客，我喜欢自己造东西。但……</p><p>如果你拥有一家建筑公司，你就不会想着自己造一辆翻斗车。你肯定不会维持一条供应链来重构翻斗车（这可是一条很大的供应链）。但你可以学会驾驶一辆。</p>',9)),r("p",null,[t[1]||(t[1]=e("好吧，我的这个比喻很粗糙，但很容易理解。易用性是相对的，易于维护是相对的，易于装配也是相对的。这实际上取决于你想要做什么。",-1)),n(s,{href:"https://kubernetes.io/"},{default:u(()=>[...t[0]||(t[0]=[e("Kubernetes",-1)])]),_:1}),t[2]||(t[2]=e(" 也不例外。",-1))]),t[19]||(t[19]=r("p",null,"一次性构建 Kubernetes 并不太难。配置好 Kubernetes 呢？好吧，这稍微难一些。你如何看待 KubeCon？它们又宣布了多少新项目？哪些是“真实的”呢？而你应该学习哪些？你对 Harbour、TikV、NATD、Vitess，开放策略代理有多深入的了解？更不用说 Envoy、eBPF 和 Linux 中的一系列底层技术？这就像是 1904 年工业革命爆发时建造翻斗车一样，你要弄清楚使用的螺钉、螺栓、金属和活塞。（有没有蒸汽朋克在这里吗？）",-1)),t[20]||(t[20]=r("p",null,"像翻斗车一样构造和配置 Kubernetes 是一个技术问题，如果你从事金融服务、零售、生物研究、食品服务等等，这可能不是你应该做的事情。但是，学习如何驾驶 Kubernetes 肯定是你应该学习的东西。",-1)),t[21]||(t[21]=r("p",null,"Kubernetes 就像一辆翻斗车，因其可以解决的各种技术问题（以及它所拖带的生态系统）而优雅。所以，我会给你一句引用的话，这是我的一位计算机科学教授在我大学的第一年告诉我们的，她说，“有一天，你会看到一段代码并对自己说，‘真特么优雅！’”",-1)),t[22]||(t[22]=r("p",null,"Kubernetes 很优雅。",-1)),t[23]||(t[23]=r("hr",null,null,-1)),r("p",null,[t[4]||(t[4]=e("via: ",-1)),n(s,{href:"https://opensource.com/article/19/6/kubernetes-dump-truck"},{default:u(()=>[...t[3]||(t[3]=[e("https://opensource.com/article/19/6/kubernetes-dump-truck",-1)])]),_:1})]),r("p",null,[t[9]||(t[9]=e("作者：",-1)),n(s,{href:"https://opensource.com/users/fatherlinux"},{default:u(()=>[...t[5]||(t[5]=[e("Scott McCarty",-1)])]),_:1}),t[10]||(t[10]=e(" 选题：",-1)),n(s,{href:"https://github.com/lujun9972"},{default:u(()=>[...t[6]||(t[6]=[e("lujun9972",-1)])]),_:1}),t[11]||(t[11]=e(" 译者：",-1)),n(s,{href:"https://github.com/wxy"},{default:u(()=>[...t[7]||(t[7]=[e("wxy",-1)])]),_:1}),t[12]||(t[12]=e(" 校对：",-1)),n(s,{href:"https://github.com/wxy"},{default:u(()=>[...t[8]||(t[8]=[e("wxy",-1)])]),_:1})]),r("p",null,[t[15]||(t[15]=e("本文由 ",-1)),n(s,{href:"https://github.com/LCTT/TranslateProject"},{default:u(()=>[...t[13]||(t[13]=[e("LCTT",-1)])]),_:1}),t[16]||(t[16]=e(" 原创编译，",-1)),n(s,{href:"https://linux.cn/"},{default:u(()=>[...t[14]||(t[14]=[e("Linux中国",-1)])]),_:1}),t[17]||(t[17]=e(" 荣誉推出",-1))])])}const w=p(d,[["render",m]]);export{g as __pageData,w as default};
